    private static void CheckDoorDamageCases() // Check complete breaches, not only HP arithmetic.
    { // Begin controlled cases.
        Check("Remembered-door attacks consume opportunities and eventually allow contact", () => // Observe a closed door buying time before the zombie reaches the human.
        { // Begin the complete breach lifecycle.
            World world = EncounterScenarios.DoorBreach(); Run(world, 1); Require(world.DoorHealthAt(3, 2) == 100 && world.TerrainRevision == 0, "Door took damage outside the attacker's opportunity."); Run(world, 1); Require(world.DoorHealthAt(3, 2) == 84 && world.ActorAt(1).x == 4 && world.DoorConditionRevision == 1 && world.TerrainRevision == 0, "First attack moved the zombie or changed collision before a breach."); string paused = State(world); TickClock clock = new TickClock(); clock.Advance(100, world.Step); Require(State(world) == paused, "Paused door attacks advanced."); World resumed = Documents.ParseSave(paused); Run(world, 29); Run(resumed, 29); Require(world.Tick == 31 && world.DoorHealthAt(3, 2) == 4 && world.TerrainAt(3, 2) == Terrain.DoorClosed, "Door broke before its seventh baseline hit."); world.Step(); resumed.Step(); Require(world.DoorHealthAt(3, 2) == 0 && world.TerrainAt(3, 2) == Terrain.DoorOpen && world.ActorAt(1).x == 4 && world.TerrainRevision == 1, "Breaking failed to open the door or granted an extra movement step."); Require(State(world) == State(resumed), "Damaged-door save continuation drifted across the breach."); resumed = Documents.ParseSave(State(world)); Run(world, 5); Run(resumed, 5); Require(world.ActorAt(1).x == 3 && world.ActorAt(0).rejectedShelterId == 27, "Zombie did not enter the breach or human did not reassess its observed shelter."); Run(world, 5); Run(resumed, 5); Require(world.ActorAt(0).turnAtTick > world.Tick && world.ActorAt(0).health == 90 && world.DoorHealthAt(3, 2) == 0, "Zombie did not reach the trapped human after the breach."); Require(State(world) == State(resumed), "Broken-door save continuation changed entry or infection."); Inspect(world); // Door durability, human observation and pursuit share the same authoritative clock.
        }); // Finish lifecycle acceptance.
        Check("Expired memory, idle wandering and solid windows do not cause door attacks", () => // Damage requires an active remembered route to this actual door.
        { // Begin attack eligibility acceptance.
            World world = EncounterScenarios.DoorBreach(); SaveDocument saved = world.Capture(); saved.actors[1].searchUntilTick = 7; world = World.Restore(saved); Run(world, 6); Require(world.DoorHealthAt(3, 2) == 84, "Recent sighting did not permit one attack."); Run(world, 1); Require(world.ActorAt(1).targetId == 0 && world.DoorHealthAt(3, 2) == 84, "Expired memory permitted another attack."); Run(world, 50); Require(world.DoorHealthAt(3, 2) == 84 && world.TerrainAt(3, 2) == Terrain.DoorClosed, "Idle wandering kept damaging a forgotten door."); // Damage persists without granting unlimited pursuit.
            world = EncounterScenarios.DoorBreach(); saved = world.Capture(); saved.actors[1].targetId = 0; saved.actors[1].lastSeenX = 0; saved.actors[1].lastSeenY = 0; saved.actors[1].searchUntilTick = 0; world = World.Restore(saved); Run(world, 50); Require(world.DoorHealthAt(3, 2) == 100, "Targetless zombie attacked an arbitrary nearby door."); // A chance move cannot become a breach action.
            WorldMap map = new WorldMap(5, 1); map.Set(2, 0, Terrain.Window); world = new World(map, 4, encounter: true); int id; world.TrySpawn(Species.Human, 3, 0, out id); world.TrySpawn(Species.Zombie, 1, 0, out id); saved = world.Capture(); saved.actors[1].targetId = 1; saved.actors[1].lastSeenX = 3; saved.actors[1].searchUntilTick = 75; world = World.Restore(saved); Run(world, 20); Require(world.ActorAt(1).x == 1 && world.TerrainAt(2, 0) == Terrain.Window && world.DoorConditionRevision == 0, "Door attacks extended to a solid window or crossed it."); // Window breaking is outside this milestone.
        }); // Finish eligibility acceptance.
        Check("Door damage uses strength, respects stagger and combines attackers deterministically", () => // Stable identity order must resolve shared door damage reproducibly.
        { // Begin strength and action timing acceptance.
            World world = EncounterScenarios.DoorBreach(); SaveDocument saved = world.Capture(); saved.actors[1].strength = 10; world = World.Restore(saved); Run(world, 2); Require(world.DoorHealthAt(3, 2) == 70, "Strength-ten attack did not use the published provisional damage."); world = EncounterScenarios.DoorBreach(); saved = world.Capture(); saved.actors[1].staggerUntilTick = 3; world = World.Restore(saved); Run(world, 2); Require(world.DoorHealthAt(3, 2) == 100, "Staggered zombie attacked the door."); Run(world, 5); Require(world.DoorHealthAt(3, 2) == 84, "Attack did not resume on its next eligible opportunity."); // Stagger obeys the existing defensive clock.
            world = EncounterScenarios.DoorBreach(); int id; Require(world.TrySpawn(Species.Zombie, 4, 2, out id), "Shared attacker spawn failed."); saved = world.Capture(); saved.actors[2].targetId = 1; saved.actors[2].lastSeenX = 3; saved.actors[2].lastSeenY = 2; saved.actors[2].searchUntilTick = 75; world = World.Restore(saved); Run(world, 3); Require(world.DoorHealthAt(3, 2) == 68, "Two attackers did not share one door's condition."); World resumed = Documents.ParseSave(State(world)); Run(world, 14); Run(resumed, 14); Require(world.DoorHealthAt(3, 2) == 0 && world.Tick == 17 && State(world) == State(resumed), "Shared attacks did not produce one deterministic breach."); Inspect(world); // Damage clamps to zero rather than becoming negative or duplicating doors.
        }); // Finish shared attack acceptance.
        Check("Door conditions survive map export, opening and ownership boundaries", () => // Neither saving nor ordinary door operation may silently repair damage.
        { // Begin map persistence acceptance.
            WorldMap map = new WorldMap(5, 5, authoringJson: "{\"retained\":true}"); map.Set(3, 2, Terrain.DoorClosed); Require(map.Capture().schemaVersion == 1 && !Documents.Encode(map.Capture()).Contains("\"doors\""), "Intact maps no longer retain the original contract."); map.SetDoorHealth(3, 2, 84); MapDocument document = map.Capture(); Require(document.schemaVersion == 2 && document.doors.Length == 1 && document.doors[0].health == 84, "Damaged map did not use explicit sparse version-two condition."); WorldMap restored = Documents.ParseMap(Documents.Encode(document)); restored.Set(3, 2, Terrain.DoorOpen); restored.Set(3, 2, Terrain.DoorClosed); Require(restored.DoorHealthAt(3, 2) == 84 && restored.AuthoringJson == map.AuthoringJson, "Opening, closing or export repaired damage or lost authoring data."); restored.SetDoorHealth(3, 2, 0); Reject(() => restored.Set(3, 2, Terrain.DoorClosed)); Require(restored.Get(3, 2) == Terrain.DoorOpen && restored.DoorHealthAt(3, 2) == 0, "A broken door could be closed."); World live = new World(restored, encounter: true); MapDocument detached = live.Capture().map; detached.doors[0].health = 99; restored.SetDoorHealth(3, 2, 100); restored.Set(3, 2, Terrain.DoorClosed); Require(live.DoorHealthAt(3, 2) == 0 && live.TerrainAt(3, 2) == Terrain.DoorOpen && restored.Capture().schemaVersion == 1, "Caller edits repaired a live breach or left unnecessary condition records."); Require(Documents.ParseMap(Documents.Encode(live.Capture().map)).DoorHealthAt(3, 2) == 0, "Map-only export lost the broken door."); SaveDocument saved = live.Capture(); saved.rulesVersion = EncounterRules.WanderVersion; Reject(() => World.Restore(saved)); // Earlier rules cannot interpret condition-bearing terrain as an indestructible door.
        }); // Finish map persistence acceptance.
        Check("Visible breaches invalidate shelters without revealing hidden structural damage", () => // Observation remains the boundary for shelter knowledge.
        { // Begin observed condition acceptance.
            World world = EncounterScenarios.DoorBreach(); SaveDocument saved = world.Capture(); saved.actors = new[] { saved.actors[0] }; WorldMap map = WorldMap.Restore(saved.map); map.SetDoorHealth(3, 2, 0); saved.map = map.Capture(); world = World.Restore(saved); Run(world, 1); Require(world.ActorAt(0).shelterId == 0 && world.ActorAt(0).rejectedShelterId == 27 && world.DoorHealthAt(3, 2) == 0, "Human retained a shelter after seeing its breached opening."); // This sighting contains no zombie and must still recognize the physical breach.
            saved = EncounterScenarios.ShelterEntry().Capture(); saved.rulesVersion = EncounterRules.Version; saved.actors = new[] { saved.actors[0] }; saved.actors[0].x = 2; saved.actors[0].y = 3; saved.actors[0].shelterId = 51; saved.actors[0].shelterX = 2; saved.actors[0].shelterY = 3; saved.actors[0].shelterState = ShelterState.Inside; map = WorldMap.Restore(saved.map); map.SetDoorHealth(5, 5, 0); saved.map = map.Capture(); world = World.Restore(saved); Run(world, 1); Require(world.ActorAt(0).shelterId == 51 && world.ActorAt(0).rejectedShelterId == 0, "Human learned about a breach behind its blocked sightline."); // The existing corner-occlusion model still controls what the human sees.
        }); // Finish perception acceptance.
        Check("Malformed sparse door records reject before replacing map or run state", () => // Validate the new format rather than silently discarding unknown damage.
        { // Begin corrupted condition cases.
            World world = EncounterScenarios.DoorBreach(); Run(world, 2); string before = State(world); MapDocument map = world.Capture().map; map.doors[0].x = -1; Reject(() => WorldMap.Restore(map)); map = world.Capture().map; map.doors[0].x = 8; Reject(() => WorldMap.Restore(map)); map = world.Capture().map; map.doors[0].health = -1; Reject(() => WorldMap.Restore(map)); map = world.Capture().map; map.doors[0].health = 100; Reject(() => WorldMap.Restore(map)); map = world.Capture().map; map.doors[0].health = 0; Reject(() => WorldMap.Restore(map)); map = world.Capture().map; map.doors = new[] { map.doors[0], map.doors[0] }; Reject(() => WorldMap.Restore(map)); map = world.Capture().map; map.doors[0] = null; Reject(() => WorldMap.Restore(map)); map = world.Capture().map; map.schemaVersion = 1; Reject(() => WorldMap.Restore(map)); map = world.Capture().map; map.doors = new DoorConditionDocument[0]; Reject(() => WorldMap.Restore(map)); map = world.Capture().map; map.schemaVersion = 3; Reject(() => WorldMap.Restore(map)); Require(State(world) == before, "Rejected condition edits changed the live world."); // Refuse invalid coordinates, terrain, health, duplicates, nulls and unsupported versions.
        }); // Finish corruption acceptance.
        Check("Prototype-nine saves retain independently recorded indestructible-door behavior", () => // Prior working runs require an explicit door-breaking update.
        { // Begin prior-release compatibility.
            string folder = Path.Combine(AppContext.BaseDirectory, "Fixtures"); World world = Documents.ParseSave(File.ReadAllText(Path.Combine(folder, "encounter-v9-input.json"))); Require(world.ZombieWandering && !world.DoorBreaking, "Previous wandering save silently gained door attacks."); Run(world, 200); Require(State(world) == State(Documents.ParseSave(File.ReadAllText(Path.Combine(folder, "encounter-v9-expected.json")))), "Prior wandering/door continuation drifted."); // Expected state came from independently executing commit afca45e.
        }); // Finish compatibility acceptance.
    } // Finish door damage cases.
